CSS="""@page{size:A4;margin:16mm}body{font-family:Poppins,Arial,sans-serif;color:#0F1A23;font-size:11.5pt;line-height:1.5}
h1{font-size:24pt;margin:0}.sub{color:#5b6b78;font-weight:500;margin:6px 0 16px}.kw{display:inline-block;background:#FFA500;color:#111;font-weight:800;padding:3px 10px;border-radius:6px}
.q{border:2px solid #e3e8ee;border-radius:14px;padding:12px 16px;margin:0 0 12px;break-inside:avoid}.q h2{font-size:14pt;margin:0 0 6px}.q h2 b{display:inline-block;width:30px;height:30px;border-radius:8px;background:#0F1A23;color:#FCF9E6;text-align:center;margin-right:8px}
.p{background:#0F1A23;color:#FCF9E6;border-radius:10px;padding:10px 14px;white-space:pre-wrap}.why{color:#5b6b78;font-size:10pt;margin-top:6px}.foot{margin-top:14px;font-size:9.5pt;color:#5b6b78}"""
for n,g in G.items():
  body="".join(f'<div class="q"><h2><b>{i+1}</b>{html.escape(t)}</h2><div class="p">{html.escape(p)}</div>'+(f'<div class="why">{html.escape(wy)}</div>' if wy else '')+'</div>' for i,(t,p,wy) in enumerate(g['items']))
  doc=f'<!doctype html><html lang="fr"><head><meta charset="utf-8"><title>{html.escape(g["titre"])}</title><link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800&display=swap" rel="stylesheet"><style>{CSS}</style></head><body><h1>{html.escape(g["titre"])}</h1><div class="sub">{html.escape(g["sous"])} · Épisode {n} du journal « Mon quotidien d\'entrepreneur avec l\'IA » · mot-clé <span class="kw">{g["kw"]}</span></div>{body}<div class="foot">Michael Kebail-Ali · michael.foodeatup.fr · Les réponses de Claude sont des propositions : vérifie les chiffres et les règles qui s\'appliquent à ton activité.</div></body></html>'
  open(f'guide-episode{n}.html','w').write(doc)
json.dump({n:dict(slug=g['slug'],kw=g['kw'],titre=g['titre'],sous=g['sous'],items=g['items']) for n,g in G.items()},open('guides.json','w'),ensure_ascii=False,indent=1)
